function buildChemQuestionBank(d, chapterIndex){
 const bank=[];
 d.notes.forEach((note,i)=>{
  bank.push({type:'normal',q:`Explain this key concept: ${note}`,a:note});
 });
 d.qs.forEach((item,i)=>bank.push({type:'important',q:item[0],a:item[1]}));
 const extraImportant=[
  {q:`Explain how the main ideas in ${d.title.toLowerCase()} help predict or explain chemical behaviour.`,a:d.desc},
  {q:`Write a short exam-style note on the most important laws, definitions and conditions in ${d.title.toLowerCase()}.`,a:d.notes.join(' ')}
 ];
 extraImportant.forEach(x=>bank.push({type:'important',q:x.q,a:x.a}));
 d.notes.forEach((note,i)=>{
  bank.push({type:'important',q:`Important ${i+1}: State and explain the principle represented by this statement: ${note}`,a:note});
  bank.push({type:'important',q:`Important ${i+6}: Give a reason or an application based on this concept: ${note}`,a:`This concept matters because it is used to explain and predict chemical properties or calculations. ${note}`});
  bank.push({type:'important',q:`Important ${i+11}: What would you write in a 2–3 mark answer about: ${note.split('.')[0]}?`,a:note});
 });
 d.notes.forEach((note,i)=>bank.push({type:'revision',q:`Quick revision ${i+1}: State the key fact or rule related to: ${note.split('.')[0]}.`,a:note}));
 numericalSets[chapterIndex].forEach(([q,a])=>bank.push({type:'numerical',q,a}));
 return bank;
}

