function buildGeneralBank(subject, chapter){
 const concepts=parseConcepts(chapter), bank=[];
 concepts.forEach((c,i)=>bank.push({type:'normal',q:`Define ${c.term}.`,a:c.easy}));
 concepts.forEach(c=>{
   bank.push({type:'important',q:`Explain ${c.term} in your own words.`,a:c.easy});
   bank.push({type:'important',q:`Why is ${c.term} important in ${chapter[0]}?`,a:`${c.easy} It is important because it helps explain the main ideas and applications in ${chapter[0]}.`});
   bank.push({type:'important',q:`Give an example or practical application of ${c.term}.`,a:`${c.easy} Example or application: connect this idea to a real organism, physical situation, mathematical problem or text studied in this chapter.`});
   bank.push({type:'important',q:`Write a short exam answer about ${c.term}, including its meaning and one key point.`,a:`${c.term}: ${c.easy} Key point: use the definition accurately and explain how it connects to ${chapter[0]}.`});
 });
 concepts.forEach(c=>bank.push({type:'revision',q:`Quick check: What does ${c.term} mean?`,a:c.easy}));
 const appPrompts = subject==='Physics' ? [
   ['A measured quantity is written with a number but no unit. What is missing and why?','A physical measurement needs both a numerical value and a unit so that its size is meaningful and comparable.'],
   ['Describe the first step you would take when solving a numerical from this chapter.','Write the given values with SI units, identify the required quantity, choose the relevant relation, substitute carefully and check the unit.'],
   ['A student gets an unexpected result. Name two checks to make.','Check unit conversions and significant figures, then check whether the chosen equation and signs match the physical situation.'],
   ['Explain one real-life situation where a concept from this chapter is used.','Link the chapter concept to an observable situation and explain the cause using the relevant physical principle.'],
   ['A graph is provided for a quantity in this chapter. What should you inspect first?','Read the axis labels and units, identify the slope or area if physically meaningful, and describe the trend before calculating.']
 ] : subject==='Mathematics' ? [
   ['How should you begin a problem from this chapter?','Identify what is given and what must be found, write the relevant definition or formula, then solve one step at a time.'],
   ['Why should you show intermediate steps in a mathematics solution?','Steps make the reasoning clear, help locate mistakes and allow method marks even if the final arithmetic is incorrect.'],
   ['How can you check whether your final answer is reasonable?','Substitute it back into the original condition, check restrictions on the domain and verify signs or units where relevant.'],
   ['Create a simple real-life situation where this chapter could be useful.','Choose quantities that fit the chapter, define the variables and explain how the mathematical relationship models the situation.'],
   ['What is a common mistake to avoid in this chapter?','Do not skip definitions or restrictions; write each algebraic step clearly and check that every transformation is valid.']
 ] : subject==='English' ? [
   ['How can you support an interpretation of a literary text?','Make a clear point, refer to a relevant incident or image from the text, and explain how it supports your interpretation.'],
   ['What makes a short-answer response effective?','Answer the exact question, include relevant textual detail and avoid retelling the whole story.'],
   ['How can a writer create a clear paragraph?','Begin with a topic sentence, develop one central idea with supporting details and finish with a linking or concluding sentence.'],
   ['How should you explain a theme?','Name the theme, show where it appears in the text and explain what the reader learns from it.'],
   ['How can you improve vocabulary without memorising isolated words?','Learn each word with its meaning, context, synonym or antonym and one original sentence.']
 ] : subject==='Arabic' ? [
   ['كوّن جملة قصيرة باستخدام كلمة من هذا الدرس.','اكتب جملة صحيحة وواضحة، ثم راجع ترتيب الكلمات والتذكير والتأنيث وعلامات الترقيم.'],
   ['لماذا يساعدك السياق على فهم كلمة عربية جديدة؟','لأن الكلمات والجمل المحيطة توضح المعنى المقصود وتساعد على اختيار المعنى المناسب.'],
   ['اكتب مثالاً من الحياة اليومية على مهارة هذا الدرس.','اختر موقفاً مألوفاً مثل المدرسة أو المنزل أو التسوق، واستخدم المفردات والقواعد التي تعلمتها.'],
   ['كيف تراجع إجابتك قبل تسليمها؟','راجع المعنى والإملاء وترتيب الكلمات ومطابقة الفعل والصفة للاسم عند الحاجة.'],
   ['ما الفرق بين حفظ القاعدة واستخدامها؟','حفظ القاعدة يعني معرفة شرحها، أما استخدامها فيعني تطبيقها بصورة صحيحة في جملة أو موقف.']
 ] : [
   ['Explain one real-life application of this chapter.','Identify the concept, describe the situation and explain how the concept helps us understand it.'],
   ['What evidence or observation could support this idea?','Use a relevant example, observation, diagram or textbook activity and explain what it demonstrates.'],
   ['How would you explain this topic to a younger student?','Use simple words, one clear example and a short step-by-step explanation.'],
   ['What is one common misconception about this topic?','A common mistake is memorising a term without understanding its conditions or application. Explain the definition and give an example.'],
   ['Write a two-sentence summary of this chapter.','State the central idea of the chapter and connect it to one important concept or application.']
 ];
 const subjectIndex=extraSubjects[subject].indexOf(chapter);
 if(solvedExamples[subject] && solvedExamples[subject][subjectIndex]) appPrompts[4]=solvedExamples[subject][subjectIndex];
 appPrompts.forEach(x=>bank.push({type:'application',q:x[0],a:x[1]}));
 return bank;
}
function generalQuestionMarkup(bank, heading){
 const labels={normal:'Normal',important:'Important',revision:'Quick revision',application:'Application / worked practice'};
 const counts={all:bank.length};Object.keys(labels).forEach(k=>counts[k]=bank.filter(q=>q.type===k).length);
 return `<div class="question-bank-head"><div><h3>${heading}</h3><p><b>${counts.all} questions in this chapter</b> · 5 normal · 20 important · 5 quick revision · 5 application/practice</p></div></div><div class="question-filters"><button class="q-filter active" data-qfilter="all">All (${counts.all})</button>${Object.keys(labels).map(k=>`<button class="q-filter" data-qfilter="${k}">${labels[k]} (${counts[k]})</button>`).join('')}</div><div id="generalQuestionList">${bank.map((q,i)=>`<div class="question chem-question" data-qtype="${q.type}"><div class="question-meta">${labels[q.type].toUpperCase()} · QUESTION ${i+1}</div><h4>${i+1}. ${q.q}</h4><button class="reveal" data-reveal="${i}">Show explanation / answer</button><div class="answer" id="answer${i}">${q.a}</div></div>`).join('')}</div>`;
}
function renderDefinitions(chapter){const cs=parseConcepts(chapter);return `<div class="revision-banner"><b>Learn the words before memorising the chapter</b><p>Each definition has a simple meaning. Read it, say it in your own words, then try to give your own example.</p></div><div class="notes-grid">${cs.map((c,i)=>`<div class="note"><b>${i+1}. ${c.term}</b><p>${c.easy}</p><small><b>Study tip:</b> Explain this term to a friend in one sentence.</small></div>`).join('')}</div>`}
